/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Naive, readable ATAX kernel:
#   tmp = A * x
#   y   = A^T * tmp
#
# We will schedule this into a tiled and parallel version below.

@proc
def atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # y[j] = 0 for all j
    for j_init in seq(0, n):
        y[j_init] = 0.0

    # tmp[i] = sum_j A[i,j] * x[j]
    for i_tmp in seq(0, m):
        tmp[i_tmp] = 0.0
        for j_tmp in seq(0, n):
            tmp[i_tmp] += A[i_tmp, j_tmp] * x[j_tmp]

    # y[j] = sum_i A[i,j] * tmp[i]
    # (This is A^T * tmp.)
    for j_y in seq(0, n):
        for i_y in seq(0, m):
            y[j_y] += A[i_y, j_y] * tmp[i_y]


# ----------------------------------------------------------------------
# Scheduling: tile the long "n" dimension and parallelize outer loops.
# We parallelize:
#   - the initialization of y
#   - the rows of tmp = A * x
#   - tiles of y's columns in y = A^T * tmp
#
# For the tmp computation (A * x), we tile j_tmp and unroll the
# inner tile to expose vectorization, and parallelize over i_tmp.
# For the y update (A^T * tmp), we iterate j_y outermost, tile j_y,
# unroll the tile, and parallelize across tiles (no cross-tile
# dependencies because each tile touches a disjoint slice of y).

TILE_N = 32  # Tuneable tile size along the N (columns) dimension

p = atax_base

# 1) Parallelize y initialization over j_init
j_init = p.find_loop("j_init")
p = parallelize_loop(p, j_init)

# 2) Optimize tmp = A * x
#    - Tile j_tmp
#    - Unroll inner tile for better ILP / vectorization
#    - Parallelize across rows i_tmp
j_tmp = p.find_loop("j_tmp")
p = divide_loop(p, j_tmp, TILE_N, ("j_tmp_outer", "j_tmp_inner"))

j_tmp_inner = p.find_loop("j_tmp_inner")
p = unroll_loop(p, j_tmp_inner)

i_tmp = p.find_loop("i_tmp")
p = parallelize_loop(p, i_tmp)

# 3) Optimize y = A^T * tmp
#    - j_y is already outermost; tile it
#    - Unroll inner tile
#    - Parallelize across outer tiles (disjoint ranges of y)
j_y = p.find_loop("j_y")
p = divide_loop(p, j_y, TILE_N, ("j_y_outer", "j_y_inner"))

j_y_inner = p.find_loop("j_y_inner")
p = unroll_loop(p, j_y_inner)

j_y_outer = p.find_loop("j_y_outer")
p = parallelize_loop(p, j_y_outer)

# 4) Clean up the IR
p = simplify(p)

# Export the scheduled kernel under the name used by the C driver
kernel_atax = rename(p, "kernel_atax")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_atax (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(x),
               (DATA_TYPE*)POLYBENCH_ARRAY(y),
               (DATA_TYPE*)POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
