def kernel_atax_unoptimized(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Basic sanity on problem sizes.
    assert m > 0
    assert n > 0

    # Initialize y to zero so we can safely accumulate into it.
    for j in seq(0, n):
        y[j] = 0.0

    # ------------------------------------------------------------
    # Phase 1: tmp = A * x
    # Each row i is independent, so this loop will be parallelized.
    # tmp[i] = sum_j A[i, j] * x[j]
    # ------------------------------------------------------------
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # ------------------------------------------------------------
    # Phase 2: y = A^T * tmp
    # y[j] = sum_i A[i, j] * tmp[i]
    # This keeps A accessed row-major and accumulates into y.
    # ------------------------------------------------------------
    for i in seq(0, m):
        for j in seq(0, n):
            y[j] += A[i, j] * tmp[i]


def schedule_kernel_atax(p):
    # Work on a local handle.
    q = p

    # 1. Parallelize Phase 1 over rows of A.
    #    Each iteration only touches tmp[i] and reads shared A,x.
    i_tmp = q.find_loop("i")          # first 'i' loop: tmp = A * x
    q = parallelize_loop(q, i_tmp)

    # 2. Tile the inner j loop of Phase 1 to improve cache locality
    #    for A and x and to expose a fixed inner loop for auto-vectorization.
    #    Tile size 64 is a reasonable default for modern x64 caches.
    j_tmp = q.find_loop("j")          # first 'j' loop (inside Phase 1)
    q = divide_loop(q, j_tmp, 64, ("jo", "ji"), tail="guard")

    # 3. Tile the inner j loop of Phase 2 for better locality on A and y.
    j_y = q.find_loop("j")            # first remaining 'j' loop (inside Phase 2)
    q = divide_loop(q, j_y, 64, ("jo2", "ji2"), tail="guard")

    # 4. Clean up resulting control logic.
    q = simplify(q)

    return q


# Apply the schedule and expose the final kernel under the name
# expected by the C driver.
kernel_atax_scheduled = schedule_kernel_atax(kernel_atax_unoptimized)
kernel_atax = rename(kernel_atax_scheduled, "kernel_atax")
